import { HTMLAttributes } from 'react';
import { IconProps } from '@hexa-ui/icons';

export interface BadgeCounterTypes extends HTMLAttributes<HTMLDivElement> {
  size?: 'small' | 'large';
  counterLabel?: number | string;
}

export interface BadgeStatusTypes extends HTMLAttributes<HTMLDivElement> {
  label?: string;
  type?: 'default' | 'interactive';
  color?: 'blue' | 'purple' | 'gray' | 'yellow' | 'green' | 'orange' | 'red' | 'info';
  disabled?: boolean;
}

export interface BadgeCategoryTypes extends HTMLAttributes<HTMLDivElement> {
  label?: string;
  type?: 'default' | 'interactive';
  color?: 'black' | 'green' | 'error' | 'orange' | 'purple' | 'yellow';
  disabled?: boolean;
  icon?: React.FunctionComponent<IconProps>;
}
